,EAAE,iBAAiB,EAAE,IAAI,CAAC,EAAE,EAAE,CAAC,kBAAkB,CAAC,IAAI,CAAC,EAAE,CAAC,CAAC,YAAY,GAAG,IAAI,CAAC,CAAC,EAAE,CAAC,CAAC;QAElG,MAAM,CAAC,YAAY,CAAC,CAAC,cAAc,CAAC,QAAQ,CAAC,CAAC;QAC9C,0CAA0C;QAC1C,MAAM,CAAC,YAAY,CAAC,KAAK,CAAC,CAAC,SAAS,CAAC,MAAM,CAAC,CAAC,CAAC,CAAC,SAAS,CAAC,CAAC,OAAO,CAAC;YAChE,OAAO,EAAE,KAAK;YACd,IAAI,EAAE,SAAS;SAChB,CAAC,CAAC;IACL,CAAC,CAAC,CAAC;IAEH,IAAI,CAAC,8BAA8B,EAAE,KAAK,IAAI,EAAE;QAC9C,MAAM,OAAO,GAAkB,CAAC,KAAK,EAAE,QAAQ,EAAE,EAAE,CAAC,EAAE,CAAC;QACvD,MAAM,cAAc,GAAG,IAAA,0BAAiB,EAAC,OAAO,CAAC,CAAC;QAClD,MAAM,WAAW,CAAC,cAAc,CAAC,CAAC;QAClC,MAAM,CAAC,SAAS,CAAC,UAAU,CAAC,CAAC,cAAc,CAAC,sBAAsB,EAAE;YAClE,SAAS,EAAE,YAAY;YACvB,QAAQ,EAAE,eAAe;SAC1B,CAAC,CAAC;IACL,CAAC,CAAC,CAAC;AACL,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/packages/google-cloud/test/gcpfunction/events.test.ts"],"sourcesContent":["import * as domain from 'domain';\nimport { SEMANTIC_ATTRIBUTE_SENTRY_ORIGIN, SEMANTIC_ATTRIBUTE_SENTRY_SOURCE } from '@sentry/core';\n\nimport type { Event } from '@sentry/types';\nimport { wrapEventFunction } from '../../src/gcpfunction/events';\nimport type { EventFunction, EventFunctionWithCallback } from '../../src/gcpfunction/general';\n\nconst mockStartSpanManual = jest.fn((...spanArgs) => ({ ...spanArgs }));\nconst mockFlush = jest.fn((...args) => Promise.resolve(args));\nconst mockCaptureException = jest.fn();\n\nconst mockScope = {\n  setContext: jest.fn(),\n};\n\nconst mockSpan = {\n  end: jest.fn(),\n};\n\njest.mock('@sentry/node', () => {\n  const original = jest.requireActual('@sentry/node');\n  return {\n    ...original,\n    startSpanManual: (...args: unknown[]) => {\n      mockStartSpanManual(...args);\n      mockSpan.end();\n      return original.startSpanManual(...args);\n    },\n    getCurrentScope: () => {\n      return mockScope;\n    },\n    flush: (...args: unknown[]) => {\n      return mockFlush(...args);\n    },\n    captureException: (...args: unknown[]) => {\n      mockCaptureException(...args);\n    },\n  };\n});