AsB,GAAU;EAC9C,IAAI,CAACF,mBAAmB,EAAE;IACxBA,mBAAoB,GAAE,IAAIjH,WAAK,EAAE;EACrC;EAEE,OAAOiH,mBAAmB;AAC5B;;AAEA;AACO,SAASG,wBAAwB,GAAU;EAChD,IAAI,CAACF,qBAAqB,EAAE;IAC1BA,qBAAsB,GAAE,IAAIlH,WAAK,EAAE;EACvC;EAEE,OAAOkH,qBAAqB;AAC9B;;AAEA;AACA;AACA;AACA;AACO,SAASF,YAAY,GAAiB;EAC3C,MAAMK,WAAWf,2BAAc,EAAE;EACjC,MAAMC,MAAO,GAAEC,6BAAgB,CAACa,QAAQ,CAAE;;EAE5C;EACE,IAAId,MAAM,CAACK,GAAG,EAAE;IACd,OAAOL,MAAM,CAACK,GAAG;EACrB;;EAEA;EACEL,MAAM,CAACK,MAAM,IAAInH,GAAG,CAAC6H,SAAS,EAAEH,sBAAsB,EAAE,EAAEC,wBAAwB,EAAE,CAAC;EACrF,OAAOb,MAAM,CAACK,GAAG;AACnB;;AAEA;AACA;AACA;AACA;AACO,SAASG,uBAAuB,CAACV,OAAO,EAAiC;EAC9E,MAAME,MAAO,GAAEC,6BAAgB,CAACH,OAAO,CAAC;EAExC,IAAIE,MAAM,CAACO,GAAG,EAAE;IACd,OAAOP,MAAM,CAACO,GAAG;EACrB;;EAEA;EACE,OAAOS,+BAA+B,EAAE;AAC1C;AAEA,SAASnG,SAAS,CAAIC,QAAQ,EAAmC;EACjE;EACE,OAAO2F,YAAY,EAAE,CAAC5F,SAAS,CAACC,QAAQ,CAAC;AAC3C;AAEA,SAASmG,YAAY,CAAI5H,KAAK,EAAkByB,QAAQ,EAAmC;EACzF,MAAMuF,MAAMI,YAAY,EAAG;EAC7B;EACE,OAAOJ,GAAG,CAACxF,SAAS,CAAC,MAAM;IAC7B;IACIwF,GAAG,CAACnG,WAAW,EAAE,CAACb,QAAQA,KAAM;IAChC,OAAOyB,QAAQ,CAACzB,KAAK,CAAC;EAC1B,CAAG,CAAC;AACJ;AAEA,SAAS6H,kBAAkB,CAAIpG,QAAQ,EAA4C;EACnF;EACE,OAAO2F,YAAY,EAAE,CAAC5F,SAAS,CAAC,MAAM;IACxC;IACI,OAAOC,QAAQ,CAAC2F,YAAY,EAAE,CAACrF,iBAAiB,EAAE,CAAC;EACvD,CAAG,CAAC;AACJ;;AAEA;AACA,SAAS4F,+BAA+B,GAAyB;EAC/D,OAAO;IACLV,aAAa,EAAEG,YAAY;IAC3BS,kBAAkB;IAClBrG,SAAS;IACToG,YAAY;IACZE,qBAAqB,EAAE,CAAIrH,eAAe,EAAkBgB,QAAQ,KAA4C;MAC9G,OAAOoG,kBAAkB,CAACpG,QAAQ,CAAC;IACzC,CAAK;IACDsG,eAAe,EAAE,MAAMX,YAAY,EAAE,CAACpG,QAAQ,EAAE;IAChDe,iBAAiB,EAAE,MAAMqF,YAAY,EAAE,CAACrF,iBAAiB;EAC7D,CAAG;AACH;AACA","names":["API_VERSION","parseFloat","SDK_VERSION","DEFAULT_BREADCRUMBS","Hub","constructor","client","scope","isolationScope","_version","assignedScope","Scope","setClient","assignedIsolationScope","_stack","bindClient","_isolationScope","isOlderThan","version","top","getStackTop","setupIntegrations","pushScope","getScope","clone","getStack","push","getClient","popScope","length","pop","withScope","callback","maybePromiseResult","e","isThenable","then","res","getIsolationScope","captureException","exception","hint","eventId","event_id","uuid4","syntheticException","Error","originalException","captureMessage","message","level","captureEvent","event","addBreadcrumb","breadcrumb","beforeBreadcrumb","maxBreadcrumbs","getOptions","timestamp","dateTimestampInSeconds","mergedBreadcrumb","finalBreadcrumb","consoleSandbox","emit","setUser","user","setTags","tags","setExtras","extras","setTag","key","value","setExtra","extra","setContext","name","context","getIntegration","integration","_oO","DEBUG_BUILD","logger","warn","id","captureSession","endSession","_sendSessionUpdate","layer","session","getSession","closeSession","setSession","startSession","release","environment","DEFAULT_ENVIRONMENT","userAgent","GLOBAL_OBJ","navigator","makeSession","getUser","currentSession","status","updateSession","shouldSendDefaultPii","options","Boolean","sendDefaultPii","_callExtensionMethod","method","args","carrier","getMainCarrier","sentry","getSentryCarrier","extensions","apply","makeMain","hub","getCurrentHub","acs","getAsyncContextStrategy","getGlobalHub","defaultCurrentScope","defaultIsolationScope","getDefaultCurrentScope","getDefaultIsolationScope","registry","undefined","getHubStackAsyncContextStrategy","withSetScope","withIsolationScope","withSetIsolationScope","getCurrentScope"],"sources":["../../src/hub.ts"],"sourcesContent":["/* eslint-disable max-lines */\nimport type {\n  Breadcrumb,\n  BreadcrumbHint,\n  Client,\n  Event,\n  EventHint,\n  Extra,\n  Extras,\n  Hub as HubInterface,\n  Integration,\n  IntegrationClass,\n  Primitive,\n  Scope as ScopeInterface,\n  Session,\n  SessionContext,\n  SeverityLevel,\n  User,\n} from '@sentry/types';\nimport { GLOBAL_OBJ, consoleSandbox, dateTimestampInSeconds, isThenable, logger, uuid4 } from '@sentry/utils';\n\nimport type { AsyncContextStrategy, Carrier } from './asyncContext';\nimport { getMainCarrier, getSentryCarrier } from './asyncContext';\nimport { DEFAULT_ENVIRONMENT } from './constants';\nimport { DEBUG_BUILD } from './debug-build';\nimport { Scope } from './scope';\nimport { closeSession, makeSession, updateSession } from './session';\nimport { SDK_VERSION } from './version';\n\n/**\n * API compatibility version of this hub.\n *\n * WARNING: This number should only be increased when the global interface\n * changes and new methods are introduced.\n *\n * @hidden\n */\nexport const API_VERSION = parseFloat(SDK_VERSION);\n\n/**\n * Default maximum number of breadcrumbs added to an event. Can be overwritten\n * with {@link Options.maxBreadcrumbs}.\n */\nconst DEFAULT_BREADCRUMBS = 100;\n\n/**\n * A layer in the process stack.\n * @hidden\n */\nexport interface Layer {\n  client?: Client;\n  scope: ScopeInterface;\n}\n\n/**\n * @inheritDoc\n */\nexport class Hub implements HubInterface {\n  /** Is a {@link Layer}[] containing the client and scope */\n  private readonly _stack: Layer[];\n\n  private _isolationScope: ScopeInterface;\n\n  /**\n   * Creates a new instance of the hub, will push one {@link Layer} into the\n   * internal stack on creation.\n   *\n   * @param client bound to the hub.\n   * @param scope bound to the hub.\n   * @param version number, higher number means higher priority.\n   *\n   * @deprecated Instantiation of Hub objects is deprecated and the constructor will be removed in version 8 of the SDK.\n   *\n   * If you are currently using the Hub for multi-client use like so:\n   *\n   * ```\n   * // OLD\n   * const hub = new Hub();\n   * hub.bindClient(client);\n   * makeMain(hub)\n   * ```\n   *\n   * instead initialize the client as follows:\n   *\n   * ```\n   * // NEW\n   * Sentry.withIsolationScope(() => {\n   *    Sentry.setCurrentClient(client);\n   *    client.init();\n   * });\n   * ```\n   *\n   * If you are using the Hub to capture events like so:\n   *\n   * ```\n   * // OLD\n   * const client = new Client();\n   * const hub = new Hub(client);\n   * hub.captureException()\n   * ```\n   *\n   * instead capture isolated events as follows:\n   *\n   * ```\n   * // NEW\n   * const client = new Client();\n   * const scope = new Scope();\n   * scope.setClient(client);\n   * scope.captureException();\n   * ```\n   */\n  public constructor(\n    client?: Client,\n    scope?: ScopeInterface,\n    isolationScope?: ScopeInterface,\n    private readonly _version: number = API_VERSION,\n  ) {\n    let assignedScope;\n    if (!scope) {\n      assignedScope = new Scope();\n      assignedScope.setClient(client);\n    } else {\n      assignedScope = scope;\n    }\n\n    let assignedIsolationScope;\n    if (!isolationScope) {\n      assignedIsolationScope = new Scope();\n      assignedIsolationScope.setClient(client);\n    } else {\n      assignedIsolationScope = isolationScope;\n    }\n\n    this._stack = [{ scope: assignedScope }];\n\n    if (client) {\n      // eslint-disable-next-line deprecation/deprecation\n      this.bindClient(client);\n    }\n\n    this._isolationScope = assignedIsolationScope;\n  }\n\n  /**\n   * Checks if this hub's version is older than the given version.\n   *\n   * @param version A version number to compare to.\n   * @return True if the given version is newer; otherwise false.\n   *\n   * @deprecated This will be removed in v8.\n   */\n  public isOlderThan(version: number): boolean {\n    return this._version < version;\n  }\n\n  /**\n   * This binds the given client to the current scope.\n   * @param client An SDK client (client) instance.\n   *\n   * @deprecated Use `initAndBind()` directly, or `setCurrentClient()` and/or `client.init()` instead.\n   */\n  public bindClient(client?: Client): void {\n    // eslint-disable-next-line deprecation/deprecation\n    const top = this.getStackTop();\n    top.client = client;\n    top.scope.setClient(client);\n    // eslint-disable-next-line deprecation/deprecation\n    if (client && client.setupIntegrations) {\n      // eslint-disable-next-line deprecation/deprecation\n      client.setupIntegrations();\n    }\n  }\n\n  /**\n   * @inheritDoc\n   *\n   * @deprecated Use `withScope` instead.\n   */\n  public pushScope(): ScopeInterface {\n    // We want to clone the content of prev scope\n    // eslint-disable-next-line deprecation/deprecation\n    const scope = this.getScope().clone();\n    // eslint-disable-next-line deprecation/deprecation\n    this.getStack().push({\n      // eslint-disable-next-line deprecation/deprecation\n      client: this.getClient(),\n      scope,\n    });\n    return scope;\n  }\n\n  /**\n   * @inheritDoc\n   *\n   * @deprecated Use `withScope` instead.\n   */\n  public popScope(): boolean {\n    // eslint-disable-next-line deprecation/deprecation\n    if (this.getStack().length <= 1) return false;\n    // eslint-disable-next-line deprecation/deprecation\n    return !!this.getStack().pop();\n  }\n\n  /**\n   * @inheritDoc\n   *\n   * @deprecated Use `Sentry.withScope()` instead.\n   */\n  public withScope<T>(callback: (scope: ScopeInterface) => T): T {\n    // eslint-disable-next-line deprecation/deprecation\n    const scope = this.pushScope();\n\n    let maybePromiseResult: T;\n    try {\n      maybePromiseResult = callback(scope);\n    } catch (e) {\n      // eslint-disable-next-line deprecation/deprecation\n      this.popScope();\n      throw e;\n    }\n\n    if (isThenable(maybePromiseResult)) {\n      // @ts-expect-error - isThenable returns the wrong type\n      return maybePromiseResult.then(\n        res => {\n          // eslint-disable-next-line deprecation/deprecation\n          this.popScope();\n          return res;\n        },\n        e => {\n          // eslint-disable-next-line deprecation/deprecation\n          this.popScope();\n          throw e;\n        },\n      );\n    }\n\n    // eslint-disable-next-line deprecation/deprecation\n    this.popScope();\n    return maybePromiseResult;\n  }\n\n  /**\n   * @inheritDoc\n   *\n   * @deprecated Use `Sentry.getClient()` instead.\n   */\n  public getClient<C ex